const dayNamesAr=["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];
const dayNamesEn=["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];

function riyadhParts(){
  const parts=new Intl.DateTimeFormat("en-US",{
    timeZone:"Asia/Riyadh",weekday:"short",hour:"2-digit",minute:"2-digit",hour12:false
  }).formatToParts(new Date());
  const o={}; parts.forEach(p=>o[p.type]=p.value);
  const map={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};
  return {day:map[o.weekday],minutes:Number(o.hour)*60+Number(o.minute)};
}
function minutesOf(t){
  const [h,m]=t.split(":").map(Number);
  return h*60+m;
}
function branchOpenNow(b){
  const now=riyadhParts();
  const intervals=b.hours[String(now.day)]||[];
  return intervals.some(([s,e])=>now.minutes>=minutesOf(s)&&now.minutes<minutesOf(e));
}
function fmtTime(t){
  const [h,m]=t.split(":").map(Number);
  if(currentLang==="en"){
    const period=h>=12?"PM":"AM";
    const hh=((h+11)%12)+1;
    return `${hh}:${String(m).padStart(2,"0")} ${period}`;
  }
  const period=h>=12?"م":"ص";
  const hh=((h+11)%12)+1;
  return `${hh}:${String(m).padStart(2,"0")} ${period}`;
}
function formatIntervals(intervals){
  if(!intervals||!intervals.length) return currentLang==="ar"?"مغلق":"Closed";
  return intervals.map(([s,e])=>`${fmtTime(s)} – ${fmtTime(e)}`).join(currentLang==="ar"?"، ":" / ");
}
function todayHours(b){
  const d=riyadhParts().day;
  return formatIntervals(b.hours[String(d)]||[]);
}
function weeklyHoursHTML(b){
  return Array.from({length:7},(_,d)=>`
    <div><span>${currentLang==="ar"?dayNamesAr[d]:dayNamesEn[d]}</span><b>${formatIntervals(b.hours[String(d)]||[])}</b></div>
  `).join("");
}

